import React, {useState} from 'react';
import {
  View,
  Text,
  TextInput,
  FlatList,
  TouchableOpacity,
  RefreshControl,
} from 'react-native';
import Icon from 'react-native-vector-icons/FontAwesome';
import AntIcon from 'react-native-vector-icons/AntDesign';
import MCIcon from 'react-native-vector-icons/MaterialIcons';
import {useExamResultStore} from '../../stores/dashboard';
import {useAuthStore, buildLink} from '@smarttestpro/smart-common';
import {useEffect} from 'react';
import {formatDateTime} from '../../utils';
import {EnglishIcon, MathIcon, ExamIcon2, PhysicsIcon} from '../../icons';

export default function SListExamsScreen({navigation}: any) {
  const [selectedTab, setSelectedTab] = useState('danh_sach');

  const {
    listStudentExams,
    listStudentExamsWait,
    loading,
    getListStudentExams,
    getListExamResult,
    getListStudentExamsWait,
  } = useExamResultStore();
  const {user, accessToken, refreshToken} = useAuthStore();

  useEffect(() => {
    if (listStudentExams.length === 0) {
      getListStudentExams(user.preferred_username);
    }

    getListStudentExamsWait(user.preferred_username);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const onRefresh = () => {
    getListStudentExams(user.preferred_username);
  };

  const onViewExamResult = (maDeThi: string) => {
    console.log(maDeThi);
    getListExamResult(user.preferred_username, maDeThi);
    navigation.push('ListExamResultScreen');
  };

  const renderIcon = (monHoc: string) => {
    const mon = (monHoc || '').toLocaleLowerCase();

    if (mon.includes('toán') || mon.includes('toan') || mon.includes('math')) {
      return <MathIcon />;
    } else if (
      mon.includes('tienganh') ||
      mon.includes('tiếng anh') ||
      mon.includes('english')
    ) {
      return <EnglishIcon />;
    } else if (
      mon.includes('vật lý') ||
      mon.includes('vật lí') ||
      mon.includes('physics')
    ) {
      return <PhysicsIcon />;
    }

    return <ExamIcon2 width={48} height={48} />;
  };

  const renderCourseItem = ({
    item,
    viewMode,
  }: {
    item: any;
    viewMode?: string;
  }) => (
    <View className="bg-blue-200 rounded-lg pl-3 pr-2 py-3 mb-4 flex-row items-center justify-between">
      <View className="flex-row flex-1">
        <View
          className="w-12 h-12 mr-2"
          style={{marginTop: item?.monHocName ? 20 : 8}}>
          {renderIcon(item?.monHocName)}
        </View>
        <View className="flex-1">
          {item?.monHocName && (
            <Text className="text-gray-600 text-xs">{item?.monHocName}</Text>
          )}
          <Text className="font-bold text-lg">{item?.noiDungDeThi}</Text>
          <View className="flex-row items-center mt-1">
            <AntIcon name="questioncircle" color="rgb(107 114 128)" size={16} />
            <Text className="ml-1 text-gray-600">
              {item?.soCau} Câu -&nbsp;
            </Text>
            <MCIcon
              name="access-time-filled"
              size={16}
              color="rgb(107 114 128)"
            />
            <Text className="ml-1 text-gray-600">
              {item.thoiGian.trim()} phút
            </Text>
          </View>
          {item.ngayKetThuc && item.ngayBatDau && (
            <View className="flex-row items-center mt-2">
              <Icon name="calendar" size={16} />
              <Text className="text-gray-600">
                {' '}
                {formatDateTime(item.ngayBatDau)}
                {' - '}
                {formatDateTime(item.ngayKetThuc)}
              </Text>
            </View>
          )}
          <View className="flex-row-reverse items-center mt-2 gap-x-2">
            <TouchableOpacity
              className="bg-blue-500 rounded-md h-7 px-3 flex justify-center items-center"
              onPress={() => {
                const baseUrl = 'https://smarttest.pro';
                const url = `/${buildLink('test-taking/exam/:id', {
                  id: item.maDeThi,
                })}`;
                const uri = `${baseUrl}/thanh-vien/dang-nhap?return_to=${encodeURI(
                  url,
                )}&accessToken=${encodeURI(
                  accessToken || '',
                )}&refreshToken=${encodeURI(refreshToken || '')}`;
                navigation.push('TestExamWebScreen', {
                  uri,
                });
              }}>
              <View className="flex-row gap-x-2">
                <Icon name="paper-plane-o" color="#ffffff" size={14} />
                <Text className="text-white ml-1 text-xs font-semibold">
                  Vào thi
                </Text>
              </View>
            </TouchableOpacity>
            {viewMode !== 'waiting' && (
              <TouchableOpacity
                className="bg-orange-400 flex-row rounded-md h-7 px-3 flex justify-center items-center"
                onPress={() => onViewExamResult(item.maDeThi)}>
                <Icon name="list-ul" size={14} color={'#ffffff'} />
                <Text className="text-white ml-1 text-xs font-semibold">
                  Kết quả
                </Text>
              </TouchableOpacity>
            )}
          </View>
        </View>
      </View>
    </View>
  );

  const renderDanhSachList = () => {
    return (
      <FlatList
        data={listStudentExams.sort(
          (a, b) =>
            new Date(b.ngayBatDau).getTime() - new Date(a.ngayBatDau).getTime(),
        )}
        keyExtractor={item => item.maDeThi.toString()}
        renderItem={({item}) => {
          return renderCourseItem({item});
        }}
        showsVerticalScrollIndicator={false}
        refreshControl={
          <RefreshControl
            refreshing={loading === 'loading'}
            onRefresh={onRefresh}
          />
        }
      />
    );
  };

  const renderChoThiList = () => {
    // Render the "Chờ thi" FlatList
    return (
      <FlatList
        data={listStudentExamsWait.sort(
          (a, b) =>
            new Date(b.ngayBatDau).getTime() - new Date(a.ngayBatDau).getTime(),
        )}
        keyExtractor={item => item.maDeThi.toString()}
        renderItem={({item}) => {
          return renderCourseItem({item, viewMode: 'waiting'});
        }}
        showsVerticalScrollIndicator={false}
        refreshControl={
          <RefreshControl
            refreshing={loading === 'loading'}
            onRefresh={onRefresh}
          />
        }
      />
    );
  };

  return (
    <View className="flex-1 bg-blue-100 p-3">
      <View className="flex-row">
        <TouchableOpacity onPress={() => navigation.goBack()}>
          <View className="px-1 h-10 justify-center">
            <MCIcon name="arrow-back" size={24} />
          </View>
        </TouchableOpacity>
        <View className="flex-1 flex-row items-center bg-white rounded-full px-4 mb-4">
          <TextInput
            placeholder="Nhập từ khóa"
            className="flex-1 h-10 text-gray-600"
          />
          <TouchableOpacity>
            <Icon name="sliders" size={24} color="#000" />
          </TouchableOpacity>
        </View>
      </View>

      <View className="flex-row justify-around mb-4">
        <TouchableOpacity
          className={`border-b-2 flex-1 items-center pb-2 ${
            selectedTab === 'danh_sach'
              ? 'border-blue-500'
              : 'border-transparent'
          }`}
          onPress={() => setSelectedTab('danh_sach')}>
          <Text
            className={`font-semibold ${
              selectedTab === 'danh_sach' ? 'text-blue-600' : 'text-gray-500'
            }`}>
            Danh sách
          </Text>
        </TouchableOpacity>
        <TouchableOpacity
          className={`border-b-2 flex-1 items-center pb-2 ${
            selectedTab === 'cho_thi' ? 'border-blue-500' : 'border-transparent'
          }`}
          onPress={() => setSelectedTab('cho_thi')}>
          <Text
            className={`font-semibold ${
              selectedTab === 'cho_thi' ? 'text-blue-600' : 'text-gray-500'
            }`}>
            Chờ thi
          </Text>
        </TouchableOpacity>
      </View>

      <Text className="text-gray-600 mb-4">
        Có{' '}
        {selectedTab === 'danh_sach'
          ? listStudentExams?.length
          : listStudentExamsWait.length}{' '}
        bài
      </Text>

      {/* <FlatList
        data={listStudentExams.sort(
          (a, b) =>
            new Date(b.ngayBatDau).getTime() - new Date(a.ngayBatDau).getTime(),
        )}
        keyExtractor={item => item.maDeThi.toString()}
        renderItem={renderCourseItem}
        showsVerticalScrollIndicator={false}
        refreshControl={
          <RefreshControl
            refreshing={loading === 'loading'}
            onRefresh={onRefresh}
          />
        }
      /> */}

      {selectedTab === 'danh_sach' ? renderDanhSachList() : renderChoThiList()}
    </View>
  );
}
